    g += `<path d="M${R(A[0])} ${R(A[1])}Q${R(B[0])} ${R(B[1])} ${R(C[0])} ${R(C[1])}L${R(D[0])} ${R(D[1])}Q${R(E[0])} ${R(E[1])} ${R(G[0])} ${R(G[1])}Z" fill="url(#dk${k})"/>`;
