      for (let r = 0; r < 11; r++) for (let c = 0; c < 19; c++) perf += `<circle cx="${f(53 + c * 5.2)}" cy="${f(78 + r * 5.2)}" r=".9" fill="#000" opacity=".16"/>`;
      const sc = x.score.length > 2 ? "99" : x.score;
