        (x.on ? `<g class="${P}breathe"><g opacity=".6" filter="${x.url("bs")}">${dots(84, 104, 5.2, sc, "#ffffff")}</g>${dots(84, 104, 5.2, sc, x.dk ? "#ffffff" : "#5d636c")}</g>` : "") + rows +
        `<circle cx="58" cy="138" r="2.4" fill="#000" opacity=".2"/>`;
