  const GLOW = { road: "#ff9b6b", space: "#6f8bff", fight: "#ff6b9a", golf: "#7fd45e", maze: "#4a7bff", gun: "#ffcf6b", beat: "#9a7bff", bugs: "#5bff8a", blocks: "#ffb36b", gems: "#c77bff", runner: "#7fd0ff", rocks: "#cfe6ff", climb: "#ff6b5b" };
