      [0, .5].forEach((o, pl) => { s += stick(x, P(c.W * (o + .08), 8, c.deckH), pl ? "#3fa8ff" : "#e0262f", true); for (let r = 0; r < 2; r++) for (let k = 0; k < 4; k++) s += btn(P(c.W * (o + .19 + k * .075), 4 + r * 6, c.deckH), col[k], 1.7); });
