      `<ellipse cx="${x}" cy="${y - 4}" rx="${r}" ry="${f(r * .45)}" fill="${sh(c, .3)}"/><path d="M${x} ${y - 4}L${f(x + r * .7)} ${f(y - 4 - r * .2)}" stroke="${sh(c, -.55)}" stroke-width="1"/>`;
