    const top = dusk ? "#1c2546" : sunny ? H.mix("#25426f", "#3b84d4", k) : "#283040", bot = dusk ? "#b9785e" : sunny ? H.mix("#7f9fc0", "#cfe6f7", k) : "#5a616e";
    return `<rect x="8" y="8" width="184" height="${f(y1 - 8)}" fill="${x.lg([[0, top], [1, bot]])}"/>`;
