    let d = ""; for (let y = fy + 6; y < 192; y += 7) d += `M8 ${y}H192`; for (let y = fy, i = 0; y < 192; y += 7, i++) for (let xx = 8 + (i * 23) % 40; xx < 192; xx += 40 + r() * 20) d += `M${f(xx)} ${y}v7`;
