    for (let y = Y, i = 0; y < Y + H; y += 5, i++) { d += `M${X} ${y}h${W}`; for (let xx = X + (i % 2 ? 0 : 6); xx < X + W; xx += 12) { d += `M${xx} ${y}v5`; if (r() > .55) s += `<rect x="${xx + .5}" y="${y + .5}" width="11" height="4" fill="${r() > .5 ? "#000" : "#fff"}" opacity="${(.05 + r() * .1).toFixed(2)}"/>`; } }
