      s += `<rect x="0" y="${f(i * ph)}" width="${W}" height="${f(ph)}" fill="${c}"/><rect x="0" y="${f(i * ph)}" width="${W}" height="${f(ph * .35)}" fill="#fff" fill-opacity=".07"/><path d="M0 ${f(i * ph + ph - .4)}H${W}" stroke="#000" stroke-opacity=".55" stroke-width=".9"/>`;
