    s += `<path d="${d}" stroke="#000" stroke-opacity=".32" stroke-width="1.2"/><path d="${e}" stroke="#fff" stroke-opacity=".2"/>`;
    s += rp(3, 3, W - 6, Hh - 8, 2.4) + rp(8, Hh * .04, W - 16, Hh * .15, 1.6);
