  function leafCols(x) { const h = N(), m = h.shade(x.c, -x.op * .22); return { m, l: h.shade(m, .45), d: h.shade(m, -.4) }; }
  const swingCls = (x, dir) => `${P}${x.on ? "swo" : "swc"} ${P}${dir > 0 ? "swl" : "swr"}`;

