  const steel = (x, vert) => x.lg([[0, "#6c7178"], [.2, "#e6e9ec"], [.45, "#b7bcc2"], [.7, "#eef0f2"], [1, "#6c7178"]], 0, 0, vert ? 0 : 1, vert ? 1 : 0);
