    for (let i = -4; i <= 8; i++) s += `<path d="M${f(100 + i * 18)} ${y0}L${f(100 + i * 34)} 192" stroke="#000" stroke-opacity=".12"/>`;
    for (let y = y0 + 8, k = 8; y < 192; k *= 1.35, y += k) s += `<path d="M8 ${f(y)}H192" stroke="#000" stroke-opacity=".12"/>`;
