  const base = (x, y, c) => `<rect x="8" y="${y - 9}" width="184" height="9" fill="${x.lg([[0, sh(c || "#eeeae2", .1)], [1, sh(c || "#eeeae2", -.15)]], 0, 0, 0, 1)}"/><path d="M8 ${y - 9}H192" stroke="#fff" stroke-opacity=".5"/><path d="M8 ${y}H192" stroke="#000" stroke-opacity=".3"/>`;
