    s += `<path d="${hd}" fill="${plas(x, "#25262b")}"/><path d="${rr(cx - 4, cy + 60, 8, 22, 4)}" fill="#0c0c0e"/><rect x="${cx - 3}" y="${f(cy + 61 + (x.on ? 12 * (1 - x.L) : 15))}" width="6" height="6" rx="2" fill="${x.c}"/>`;
