    s += `<path d="${body}" fill="${plas(x, x.c)}"/><path d="${body}" fill="none" stroke="${sh(x.c, -.45)}" stroke-width=".6"/>`;
    s += `<path d="${rr(X - 1, top - 6, W + 2, 14, 7)}" fill="${plas(x, sh(x.c, .06), true)}"/><path d="M${X + 8} ${top - 4}H${X + W - 8}" stroke="#fff" stroke-opacity=".6"/>`;
