  const cLG = (o, x, y, w, h) => knob(o, x + w * .16, y + h / 2, h * .22) + screen(o, x + w * .5, y + h * .42, h * .22) + stages(o, x + w * .38, y + h * .78, 6.5, WST, 1.5) + pills(o, x + w * .74, y + h * .45, 3, 7);
