      const wv = "M54 160 C70 152 84 166 100 158 C116 150 130 166 146 158";
      return out(x, `${wall(x)}${wash(x, 100, 100, 90, 72)}${contour(x, [tr, fr, wv], 16, [[60, 64], [140, 54], [100, 160]])}
${tube(x, tr, acc, 3.6)}${tube(x, fr, x.c, 3.4)}${tube(x, wv, sea, 3)}`);
