    if (!ROOT) return; const K = catalog();
    if (!K.plants.length) { ROOT.querySelector(`.${P}card`).innerHTML = `<div class="${P}hint">Loading the original drawings…</div>`; return; }
    const pl = K.P[C.plant] || K.plants[0]; C.plant = pl.id;
