      (c.cols || []).map((uu) => { const a = bp(x1, x2, yb, yf, ins, uu, 0), b = bp(x1, x2, yb, yf, ins, uu, 1); return `<path d="M${a[0]} ${+a[1] + 1}L${b[0]} ${+b[1] - 1}" stroke="#08090a" stroke-width="2.6"/>`; }).join("") +
      `<path d="M${x1 + 3} ${yf - 2}H${x2 - 3}" stroke="#55585e" stroke-width=".7"/>`;
