      if (!g.noFloor) s += `<path d="M${g.x + 4} ${fy}H${g.x + g.w - 4}L${g.x + g.w + 28} 200H${g.x - 16}Z" fill="#ffe7b0" opacity="${f2(a * .2)}"/>`;
