    if (m === "cross" || m === "h") s += `<rect x="${x}" y="${y + h / 2 - 2}" width="${w}" height="4" fill="${col}"/><rect x="${x}" y="${y + h / 2 + 2}" width="${w}" height="1" fill="#000" opacity=".15"/>`;
