    const n = a > .03 ? Math.round(1 + a * 4) : 0, fh = 8;
    const stackH = n ? n * fh * .72 + fh * .28 : 0;
    const fb = y + Math.max(stackH + 6, h * (1 - a * .92));
    const flatB = fb - stackH;
    let s = fabric(o, x, y, w, flatB - y);
