      for (let i = 0; i < 5; i++) art += `<rect x="${f(ix + r() * iw * .6)}" y="${f(iy + r() * ih * .6)}" width="${f(iw * (.2 + r() * .35))}" height="${f(ih * (.15 + r() * .35))}" fill="${pal[i]}" fill-opacity=".9"/>`;
