      b += `<rect x="80" y="132" width="19.4" height="12" rx="2" fill="${x.url("btn")}"/><rect x="100.6" y="132" width="19.4" height="12" rx="2" fill="${x.url("btn")}"/>` + chev(89.7, 138, 2.6, false, 1) + chev(110.3, 138, 2.6, true, 1);
