        `<circle cx="${cx}" cy="${cy}" r="34" fill="${x.url("dome")}"/><path d="${arc(cx, cy, 31, -75, -15)}" fill="none" stroke="#fff" stroke-opacity=".8" stroke-width="1.6" stroke-linecap="round"/>`;
